import{_ as a,o as t,c as s,a2 as r}from"./chunks/framework.CqGS6Fr9.js";const u=JSON.parse('{"title":"Backup and recovery","description":"","frontmatter":{"pageId":"admins/backup-recovery","contentRevision":5},"headers":[],"relativePath":"en/admins/backup-recovery.md","filePath":"en/admins/backup-recovery.md"}'),o={name:"en/admins/backup-recovery.md"};function i(n,e,l,c,d,p){return t(),s("div",null,[...e[0]||(e[0]=[r('<h1 id="backup-and-recovery" tabindex="-1">Backup and recovery <a class="header-anchor" href="#backup-and-recovery" aria-label="Permalink to &quot;Backup and recovery&quot;">​</a></h1><p>Applies to: Rimlink 0.9.2 · RimWorld 1.7 · protocol 1.</p><h2 id="usage" tabindex="-1">Usage <a class="header-anchor" href="#usage" aria-label="Permalink to &quot;Usage {#usage}&quot;">​</a></h2><p>Use a consistent database-and-saves backup. Online backup: <code>rimlink-tools backup --data &lt;DataDir&gt; --out &lt;backup.tar.zst&gt;</code>; without --out it goes under backups. POST /api/admin/backups creates one, GET /backups lists them, GET /backups/{name} downloads one. Automatic defaults are Backup:IntervalHours=24 and Keep=7.</p><p>Before restoring, stop the server, preserve the current directory separately and test the selected backup in isolation. <code>rimlink-tools restore --data &lt;DataDir&gt; --from &lt;backup.tar.zst&gt;</code> replaces database and saves. After startup check /health, save versions, login and unfinished deliveries. Do not connect real players to a test restore.</p><p>admin rollback for one player is not whole-server recovery. Coordinate it with escrow state and client recovery journals.</p><h2 id="restore-drill" tabindex="-1">Isolated backup restoration, step by step <a class="header-anchor" href="#restore-drill" aria-label="Permalink to &quot;Isolated backup restoration, step by step {#restore-drill}&quot;">​</a></h2><ol><li>Create a consistent archive with the supported backup tool; record time, server version, size and checksum. Keep a copy away from the server&#39;s only disk.</li><li>Choose a <strong>new test directory</strong>, not production DataDir. Ensure no server uses it. Preserve configuration/certificates separately.</li><li>Run locally:</li></ol><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rimlink-tools</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> restore</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --data</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./restore-drill</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --from</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./copies/rimlink-selected.tar.zst</span></span></code></pre></div><ol start="4"><li>Start a compatible version with DataDir=./restore-drill, a separate port and external access blocked. Do not send real clients to this copy.</li><li>Check health, world status, save version list, and opening current/selected older test-player saves; reconcile counters/mail against the chosen point. File existence alone is insufficient.</li><li>Record outcomes before planning production restore, with shutdown, preservation of current data and confirmation.</li></ol><p>Restore <strong>replaces the target database and saves</strong>. This is a procedure, not a claim that your server was tested.</p><h2 id="backup-scope" tabindex="-1">What does whole-server restore not repair? <a class="header-anchor" href="#backup-scope" aria-label="Permalink to &quot;What does whole-server restore not repair? {#backup-scope}&quot;">​</a></h2><p>The archive aligns database and save files under a lock. Do not make independent live copies or delete save-storage.lock. Older versions can depend on delta bases; restoring one .rws.zst does not restore history.</p><p>Whole-server rollback also rewinds economy/social records, while clients retain journals of newer actions. Preserve that evidence and plan reconciliation before allowing logins. “Clear everyone&#39;s outbox” is not a universal solution.</p><p>Check external modpack artifacts, source mods/licenses, service settings and secrets separately. Backup:Keep includes panel-created archives; a manual backup can evict the oldest retained one.</p><h2 id="limits" tabindex="-1">Limits and safety <a class="header-anchor" href="#limits" aria-label="Permalink to &quot;Limits and safety {#limits}&quot;">​</a></h2><p>Never delete save-storage.lock: the tool holds it with the storage lock through snapshot/packing. Older versions are not necessarily full .rws.zst files: they may be deltas. Test restorability, not just archive existence.</p><h2 id="related" tabindex="-1">See also <a class="header-anchor" href="#related" aria-label="Permalink to &quot;See also {#related}&quot;">​</a></h2><ul><li><a href="./updating">Updating server and clients</a></li><li><a href="./../developers/storage">Storage and escrow</a></li><li><a href="./../players/saves-recovery">Saves and recovery</a></li></ul>',19)])])}const k=a(o,[["render",i]]);export{u as __pageData,k as default};
